        function convertMarkdownToMarkmap(markdown) {
            const lines = markdown.split('\n');
            let currentLevel = 0;
            let markmap = { content: '', children: [] };
            let currentNode = markmap;

            for (const line of lines) {
                // Captura cabeçalhos (# heading)
                const match = line.match(/^(#+)\s+(.+)/);
                if (match) {
                    const [, hashes, content] = match;
                    const level = hashes.length - 1;

                    const node = { content, children: [] };

                    if (level > currentLevel) {
                        // Novo nível superior: adiciona ao filho atual
