                        // Nível inferior: sobe até o nível correto
                        while (level < currentLevel) {
                            currentNode = currentNode.parent;
                            currentLevel--;
                        }
                        currentNode.parent.children.push(node);
                        node.parent = currentNode.parent;
                        currentNode = node;
                    } else {
                        // Mesmo nível: adiciona ao filho atual ou ao primeiro nível
                        if (currentNode.parent) {
                            currentNode.parent.children.push(node);
                            node.parent = currentNode.parent;
                        } else {
                            markmap.children.push(node);
                            node.parent = markmap;
                        }
                        currentNode = node;
                    }

                    currentLevel = level;
                }
            }

            return markmap;
